const m3=html.match(/const J3 = \[([\s\S]*?)\];/)[1];
const J1js=[...m1.matchAll(/\['(\w+)'/g)].map(x=>x[1]);
const J3js=[...m3.matchAll(/\['(\w+)'/g)].map(x=>x[1]);
